// OBS alert server. Zero deps. POST /alert -> SSE -> overlay in OBS Browser Source.
// ponytail: no auth — binds 127.0.0.1 only, that's the trust boundary. Add a token if ever exposed.
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const PORT = Number(process.env.PORT) || 7373;
const MAX_BODY = 64 * 1024;
const OVERLAY = path.join(__dirname, 'overlay.html');

/** @type {Set<import('node:http').ServerResponse>} */
const clients = new Set();

function validate(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const text = typeof raw.text === 'string' ? raw.text.trim() : '';
  if (!text) return null;
  const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : undefined);
  const alert = { text };
  const title = str(raw.title);
  const image = str(raw.image);
  const sound = str(raw.sound);
  if (title) alert.title = title;
  if (image) alert.image = image;
  if (sound) alert.sound = sound;
  const d = Number(raw.duration);
  if (Number.isFinite(d)) alert.duration = Math.min(30000, Math.max(100, d));
  return alert; // unknown keys dropped
}

function broadcast(alert) {
  const frame = `data: ${JSON.stringify(alert)}\n\n`;
  for (const res of clients) res.write(frame);
  return clients.size;
}

function json(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) });
  res.end(body);
}

function readBody(req, cb) {
  let size = 0;
  const chunks = [];
  req.on('data', (c) => {
    size += c.length;
    if (size > MAX_BODY) {
      cb(new Error('body too large'));
      req.destroy();
      return;
    }
    chunks.push(c);
  });
  req.on('end', () => cb(null, Buffer.concat(chunks).toString('utf8')));
  req.on('error', cb);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');

  if (req.method === 'GET' && (url.pathname === '/overlay' || url.pathname === '/')) {
    fs.readFile(OVERLAY, (err, buf) => {
      if (err) return json(res, 500, { error: 'overlay.html missing' });
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
      res.end(buf);
    });
    return;
  }

  if (req.method === 'GET' && url.pathname === '/events') {
    res.writeHead(200, {
      'content-type': 'text/event-stream',
      'cache-control': 'no-store',
      connection: 'keep-alive',
    });
    res.write(': connected\n\n');
    clients.add(res);
    const ping = setInterval(() => res.write(': ping\n\n'), 15000);
    req.on('close', () => {
      clearInterval(ping);
      clients.delete(res);
    });
    return;
  }

  if (req.method === 'POST' && url.pathname === '/alert') {
    readBody(req, (err, body) => {
      if (err) return json(res, 413, { error: 'body too large' });
      let parsed;
      try {
        parsed = JSON.parse(body);
      } catch {
        return json(res, 400, { error: 'invalid JSON' });
      }
      const alert = validate(parsed);
      if (!alert) return json(res, 400, { error: 'field "text" required (non-empty string)' });
      json(res, 200, { ok: true, clients: broadcast(alert) });
    });
    return;
  }

  json(res, 404, { error: 'not found' });
});

module.exports = { server, validate };

if (require.main === module) {
  server.listen(PORT, '127.0.0.1', () => {
    console.log(`OBS alerts up.
  Browser Source URL : http://127.0.0.1:${PORT}/overlay
  Fire an alert      : curl -X POST localhost:${PORT}/alert -H 'content-type: application/json' -d '{"title":"FOLLOW","text":"bob just followed"}'`);
  });
}

// Run: node test.js   — covers the two bits with real logic: validation + SSE broadcast.
const assert = require('node:assert');
const http = require('node:http');
const { server, validate } = require('./server');

// --- validation ---
assert.strictEqual(validate(null), null);
assert.strictEqual(validate({}), null);
assert.strictEqual(validate({ text: '   ' }), null);
assert.strictEqual(validate([{ text: 'x' }]), null);
assert.deepStrictEqual(validate({ text: 'hi', evil: 1 }), { text: 'hi' });
assert.strictEqual(validate({ text: 'hi', duration: 999999 }).duration, 30000);
assert.strictEqual(validate({ text: 'hi', duration: 1 }).duration, 100);
assert.strictEqual(validate({ text: 'hi', duration: 'nope' }).duration, undefined);

const post = (port, body) =>
  new Promise((resolve) => {
    const req = http.request(
      { port, host: '127.0.0.1', method: 'POST', path: '/alert', headers: { 'content-type': 'application/json' } },
      (res) => {
        let d = '';
        res.on('data', (c) => (d += c));
        res.on('end', () => resolve({ code: res.statusCode, body: d }));
      }
    );
    req.end(body);
  });

server.listen(0, '127.0.0.1', async () => {
  const port = server.address().port;

  // open an SSE client, wait for it to register
  const frames = [];
  await new Promise((resolve) => {
    http.get({ port, host: '127.0.0.1', path: '/events' }, (res) => {
      res.on('data', (c) => frames.push(c.toString()));
      resolve();
    });
  });
  await new Promise((r) => setTimeout(r, 50));

  const ok = await post(port, JSON.stringify({ text: 'bob followed', title: 'FOLLOW' }));
  assert.strictEqual(ok.code, 200);
  assert.strictEqual(JSON.parse(ok.body).clients, 1, 'alert should reach the connected overlay');

  await new Promise((r) => setTimeout(r, 50));
  const sse = frames.join('');
  assert.match(sse, /^data: .*bob followed/m, 'SSE frame should carry the alert');
  assert.strictEqual(JSON.parse(sse.match(/^data: (.*)$/m)[1]).title, 'FOLLOW');

  assert.strictEqual((await post(port, '{"text":"")')).code, 400, 'bad JSON -> 400');
  assert.strictEqual((await post(port, '{"nope":1}')).code, 400, 'missing text -> 400');

  console.log('ok — validation + broadcast');
  process.exit(0);
});

